<section class="card form-card account-card"><div class="card-head"><div><h3><?= e($account['name']) ?></h3><p>Compte #<?= (int)$account['id'] ?> · <?= $account['is_active'] ? 'Actif' : 'Inactif' ?></p></div><a class="text-link" href="users">← Comptes</a></div>
